import{_ as a,o as t,c as i,a0 as n}from"./chunks/framework.DQOulFGV.js";const c=JSON.parse('{"title":"Kafka 消息可靠性：如何保证消息不丢失？","description":"","frontmatter":{"doc_id":"kafka-消息可靠性","title":"Kafka 消息可靠性：如何保证消息不丢失？"},"headers":[],"relativePath":"kafka/03-消息可靠性.md","filePath":"kafka/03-消息可靠性.md"}'),e={name:"kafka/03-消息可靠性.md"};function l(h,s,p,d,r,k){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="kafka-消息可靠性-如何保证消息不丢失" tabindex="-1">Kafka 消息可靠性：如何保证消息不丢失？ <a class="header-anchor" href="#kafka-消息可靠性-如何保证消息不丢失" aria-label="Permalink to &quot;Kafka 消息可靠性：如何保证消息不丢失？&quot;">​</a></h1><hr><p>消息丢失可能发生在三个环节，需要分别保障：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph 生产者端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A[&quot;acks 配置&lt;br&gt;重试机制&lt;br&gt;幂等生产者&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Broker 端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B[&quot;副本同步&lt;br&gt;ISR 机制&lt;br&gt;持久化刷盘&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph 消费者端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C[&quot;手动提交 offset&lt;br&gt;幂等消费&lt;br&gt;异常处理&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt;|消息写入| B --&gt;|消息拉取| C</span></span></code></pre></div><hr><h2 id="_1-生产者端-acks-参数" tabindex="-1">1. 生产者端：acks 参数 <a class="header-anchor" href="#_1-生产者端-acks-参数" aria-label="Permalink to &quot;1. 生产者端：acks 参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>acks 值</th><th>含义</th><th>可靠性</th><th>性能</th><th>适用场景</th></tr></thead><tbody><tr><td><code>0</code></td><td>不等待任何确认</td><td>最低（可能丢消息）</td><td>最高</td><td>日志收集（允许少量丢失）</td></tr><tr><td><code>1</code></td><td>等待 Leader 写入确认</td><td>中等（Leader 宕机可能丢）</td><td>中等</td><td>一般业务</td></tr><tr><td><code>-1</code>/<code>all</code></td><td>等待所有 ISR 副本确认</td><td>最高（不丢消息）</td><td>最低</td><td>金融、订单等核心业务</td></tr></tbody></table><blockquote><p><strong>ISR（In-Sync Replicas）</strong>：与 Leader 保持同步的副本集合。落后太多的副本会被踢出 ISR。 <strong>为什么 acks=all 不是默认值</strong>：acks=all 需要等待所有 ISR 副本确认，延迟更高。大多数业务场景可以接受极小概率的消息丢失（Leader 宕机的概率很低），用 acks=1 换取更低延迟。</p></blockquote><hr><h2 id="_2-broker-端-副本同步" tabindex="-1">2. Broker 端：副本同步 <a class="header-anchor" href="#_2-broker-端-副本同步" aria-label="Permalink to &quot;2. Broker 端：副本同步&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant P as 生产者</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant L as Leader 副本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant F1 as Follower 1(ISR)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant F2 as Follower 2(ISR)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P-&gt;&gt;L: 发送消息(acks=all)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L-&gt;&gt;F1: 同步消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L-&gt;&gt;F2: 同步消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F1--&gt;&gt;L: 确认写入</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F2--&gt;&gt;L: 确认写入</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L--&gt;&gt;P: 返回成功(所有 ISR 已确认)</span></span></code></pre></div><hr><h2 id="_3-消费者端-手动提交-offset" tabindex="-1">3. 消费者端：手动提交 Offset <a class="header-anchor" href="#_3-消费者端-手动提交-offset" aria-label="Permalink to &quot;3. 消费者端：手动提交 Offset&quot;">​</a></h2><p>消费者端保障消息不丢失的核心原则：<strong>处理成功后再提交 offset</strong>。</p><table tabindex="0"><thead><tr><th>提交方式</th><th>语义</th><th>风险</th></tr></thead><tbody><tr><td>自动提交（<code>enable.auto.commit=true</code>）</td><td>定时提交，不管处理是否成功</td><td>处理失败后 offset 已提交 → 消息丢失</td></tr><tr><td>手动提交（<code>enable.auto.commit=false</code>）</td><td>处理成功后显式提交</td><td>提交失败 → 重复消费（可通过幂等处理解决）</td></tr></tbody></table><blockquote><p><strong>生产推荐</strong>：关闭自动提交，使用手动提交。详细的提交方式（同步/异步/指定 offset）、消费语义（At Least Once / Exactly Once）和幂等消费方案，请参阅 → <a href="./12-消费语义与位移管理.html">消费语义与位移管理</a></p></blockquote><hr><h2 id="_4-幂等性-防止重复消息" tabindex="-1">4. 幂等性：防止重复消息 <a class="header-anchor" href="#_4-幂等性-防止重复消息" aria-label="Permalink to &quot;4. 幂等性：防止重复消息&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[生产者发送消息] --&gt; B{网络超时?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|是| C[重试发送]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D{Broker 已收到?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|是| E[&quot;❌ 未开启幂等：消息重复&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt;|是| F[&quot;✅ 开启幂等：Broker 去重，只保留一条&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|否| G[正常写入]</span></span></code></pre></div><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 开启幂等生产者（Producer ID + Sequence Number 去重）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">props.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enable.idempotence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 开启幂等后，acks 自动设为 all，retries 自动设为 MAX_INT</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 为什么这样设计：幂等性依赖 acks=all 保证消息写入，依赖重试保证消息不丢</span></span></code></pre></div><hr><h2 id="_5-三端保障总结" tabindex="-1">5. 三端保障总结 <a class="header-anchor" href="#_5-三端保障总结" aria-label="Permalink to &quot;5. 三端保障总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>关键配置/做法</th><th>作用</th></tr></thead><tbody><tr><td><strong>生产者</strong></td><td><code>acks=all</code> + 重试 + 幂等</td><td>确保消息成功写入所有 ISR 副本</td></tr><tr><td><strong>Broker</strong></td><td>多副本 + ISR 同步</td><td>即使 Leader 宕机，Follower 可接管</td></tr><tr><td><strong>消费者</strong></td><td>手动提交 offset + 幂等处理</td><td>确保消息处理成功后才标记已消费</td></tr></tbody></table>`,23)])])}const E=a(e,[["render",l]]);export{c as __pageData,E as default};
